begin;
do $$
#variable_conflict use_variable
declare customer uuid:=gen_random_uuid();captain uuid:=gen_random_uuid();other uuid:=gen_random_uuid();lid uuid;ids uuid[]:='{}';result jsonb;payload jsonb;i integer;runid uuid;before_n integer;
begin
 insert into auth.users(id,aud,role)values(customer,'authenticated','authenticated'),(captain,'authenticated','authenticated'),(other,'authenticated','authenticated');
 insert into public.tkt_profiles(user_id,name,phone,captain,expires_at)values(customer,'اختبار زبون خط','07900000001',false,null),(captain,'اختبار كابتن خط','07900000002',true,now()+interval '1 year'),(other,'اختبار حساب آخر','07900000003',false,null)on conflict(user_id)do update set captain=excluded.captain,expires_at=excluded.expires_at;
 insert into storage.objects(bucket_id,name)values('tkt-line-documents',customer||'/test/front.jpg'),('tkt-line-documents',customer||'/test/back.jpg');
 if (select count(*)from tkt_private.line_dates('2026-10-14',15,array[5,6]))<>15 then raise exception 'wrong service count';end if;
 if (select max(service_date)from tkt_private.line_dates('2026-10-14',15,array[5,6]))<>'2026-11-03'then raise exception 'wrong end date';end if;
 begin perform *from tkt_private.line_dates(current_date,15,array[0,1,2,3,4,5,6]);raise exception 'all days allowed';exception when others then if sqlerrm<>'INVALID_SCHEDULE'then raise;end if;end;
 payload:=jsonb_build_object('kind','school','passenger_name','راكب اختبار ثلاثي','pickup_name','البيت','destination_name','المدرسة','pickup_lat',33.5,'pickup_lng',44.4,'destination_lat',33.51,'destination_lng',44.41,'service_days',15,'excluded_days','[5,6]'::jsonb,'start_date',((now()at time zone 'Asia/Baghdad')::date+1),'departure','07:00','arrival','08:00','return_home','14:00','total_price',15000,'front_path',customer||'/test/front.jpg','back_path',customer||'/test/back.jpg');
 perform set_config('request.jwt.claim.sub',customer::text,true);
 begin perform public.tkt_lines('create',payload-'return_home');raise exception 'missing return allowed';exception when others then if sqlerrm<>'INVALID_SCHEDULE'then raise;end if;end;
 begin perform public.tkt_lines('create',jsonb_set(payload,'{return_home}','"07:30"'));raise exception 'early return allowed';exception when others then if sqlerrm<>'INVALID_SCHEDULE'then raise;end if;end;
 for i in 1..6 loop payload:=jsonb_set(payload,'{pickup_lat}',to_jsonb(case i when 1 then 33.5 when 2 then 33.507 when 3 then 33.514 when 4 then 33.503 when 5 then 33.505 else 33.55 end));result:=public.tkt_lines('create',payload);ids:=array_append(ids,(result->>'id')::uuid);end loop;
 result:=public.tkt_lines('detail',jsonb_build_object('id',ids[1]));
 if result->'line'?'front_path' or result->'line'?'back_path'then raise exception 'documents leaked';end if;
 perform set_config('request.jwt.claim.sub',captain::text,true);
 result:=public.tkt_lines('detail',jsonb_build_object('id',ids[1]));
 if result->'customer'->>'phone'<>'07900000001' then raise exception 'offer phone hidden';end if;
 if result->'line'->>'return_home'<>'14:00:00' then raise exception 'return time lost';end if;
 if result->'line'?'front_path' or result->'line'?'back_path' then raise exception 'offer documents leaked';end if;
 perform public.tkt_lines('accept',jsonb_build_object('id',ids[1]));
 if (select count(*)from tkt_private.line_suggestions(captain))<>2 then raise exception 'one line must suggest two';end if;
 if exists(select 1 from tkt_private.line_suggestions(captain)where distance_m>1000)then raise exception 'far suggestion';end if;
 begin perform public.tkt_lines('accept',jsonb_build_object('id',ids[6]));raise exception 'far line accepted';exception when others then if sqlerrm<>'LINE_TOO_FAR'then raise;end if;end;
 perform public.tkt_lines('accept',jsonb_build_object('id',ids[2]));
 if (select count(*)from tkt_private.line_suggestions(captain))<>1 then raise exception 'two lines must suggest one';end if;
 perform public.tkt_lines('accept',jsonb_build_object('id',ids[3]));
 if exists(select 1 from tkt_private.line_suggestions(captain))then raise exception 'three lines still see offers';end if;
 begin perform public.tkt_lines('accept',jsonb_build_object('id',ids[4]));raise exception 'fourth accepted';exception when others then if sqlerrm<>'MAX_THREE_LINES'then raise;end if;end;
 result:=public.tkt_lines('detail',jsonb_build_object('id',ids[1]));if result->'line'?'front_path'then raise exception 'captain documents leak';end if;
 perform set_config('request.jwt.claim.sub',other::text,true);
 begin perform public.tkt_lines('detail',jsonb_build_object('id',ids[1]));raise exception 'unrelated can read';exception when others then if sqlerrm<>'PERMISSION_DENIED'then raise;end if;end;
 select id into runid from tkt_private.line_runs where line_id=ids[1]order by service_date limit 1;
 update tkt_private.line_runs set departure_at=now()-interval '6 minutes',arrival_at=now()+interval '50 minutes'where id=runid;
 update tkt_private.line_runs set service_date=(now()at time zone 'Asia/Baghdad')::date where id=runid;
 perform set_config('request.jwt.claim.sub',captain::text,true);
 result:=public.tkt_line_history();if jsonb_array_length(result)<>1 or result->0->>'line_id'<>ids[1]::text then raise exception 'line history incorrect';end if;
 if result->0?'front_path' or result->0?'back_path'then raise exception 'history documents leaked';end if;
 perform set_config('request.jwt.claim.sub',other::text,true);
 if public.tkt_line_history()<>'[]'::jsonb then raise exception 'unrelated history visible';end if;
 perform tkt_private.line_clock();
 if not exists(select 1 from public.tkt_notifications where user_id=captain and event_key='line_due:'||runid)then raise exception 'no due reminder';end if;
 if not exists(select 1 from public.tkt_notifications where user_id=customer and event_key='line_late:'||runid)then raise exception 'no late alert';end if;
 select count(*)into before_n from public.tkt_notifications where event_key in('line_due:'||runid,'line_late:'||runid);
 perform tkt_private.line_clock();
 if (select count(*)from public.tkt_notifications where event_key in('line_due:'||runid,'line_late:'||runid))<>before_n then raise exception 'duplicate alerts';end if;
 perform set_config('request.jwt.claim.sub',captain::text,true);
 update public.tkt_profiles set lat=33.5,lng=44.4,location_at=now()where user_id=captain;
 perform public.tkt_lines('run_state',jsonb_build_object('id',ids[1],'run_id',runid,'state','heading'));
 perform public.tkt_lines('run_state',jsonb_build_object('id',ids[1],'run_id',runid,'state','arrived'));
 if tkt_private.line_next(captain,ids[1])is not null then raise exception 'future line selected';end if;
 begin perform public.tkt_lines('depart',jsonb_build_object('id',ids[1],'run_id',runid,'mode','next'));raise exception 'future next permitted';exception when others then if sqlerrm<>'NEXT_LINE_NOT_DUE'then raise;end if;end;
 if not exists(select 1 from tkt_private.line_runs where id=runid and state='arrived')then raise exception 'failed next modified current run';end if;
 update tkt_private.line_runs set service_date=(now()at time zone 'Asia/Baghdad')::date,departure_at=now()-interval '1 minute',arrival_at=now()+interval '55 minutes'where id=(select id from tkt_private.line_runs where line_id=ids[2]order by service_date limit 1);
 result:=public.tkt_lines('depart',jsonb_build_object('id',ids[1],'run_id',runid,'mode','next'));
 if result->'next_line'->>'line_id'<>ids[2]::text then raise exception 'wrong next line';end if;
 if not exists(select 1 from tkt_private.line_runs where id=runid and state='picked_up')then raise exception 'passenger not boarded';end if;
 if jsonb_array_length(tkt_private.line_onboard(captain))<>1 then raise exception 'onboard queue incorrect';end if;
 begin perform public.tkt_lines('run_state',jsonb_build_object('id',ids[1],'run_id',runid,'state','completed'));raise exception 'delivered far from destination';exception when others then if sqlerrm<>'MUST_BE_AT_DESTINATION'then raise;end if;end;
 update public.tkt_profiles set lat=33.51,lng=44.41,location_at=now()where user_id=captain;
 perform public.tkt_lines('run_state',jsonb_build_object('id',ids[1],'run_id',runid,'state','completed'));
 if tkt_private.line_onboard(captain)<>'[]'::jsonb then raise exception 'delivered passenger remains onboard';end if;
 perform set_config('request.jwt.claim.sub',customer::text,true);
 begin perform public.tkt_lines('payment',jsonb_build_object('id',ids[1]));raise exception 'early payment allowed';exception when others then if sqlerrm<>'PAYMENT_NOT_DUE'then raise;end if;end;
 update tkt_private.lines set status='accepted',payment_status='not_due',start_date=(now()at time zone 'Asia/Baghdad')::date,end_date=(now()at time zone 'Asia/Baghdad')::date,departure='00:00',arrival=(now()at time zone 'Asia/Baghdad'-interval '1 minute')::time where id=ids[1];
 perform set_config('request.jwt.claim.sub',captain::text,true);
 perform public.tkt_lines('payment',jsonb_build_object('id',ids[1]));
 if not exists(select 1 from tkt_private.lines where id=ids[1]and payment_status='paid'and paid_by=captain and paid_at is not null)then raise exception 'direct captain receipt failed';end if;
 perform public.tkt_lines('payment',jsonb_build_object('id',ids[1]));
 update tkt_private.line_runs set state='completed'where line_id=ids[1];
 perform tkt_private.line_clock();
 if not exists(select 1 from tkt_private.lines where id=ids[1]and status='completed'and payment_status='paid')then raise exception 'completion reset paid receipt';end if;
 insert into public.tkt_admins(user_id)values(captain);
 result:=public.tkt_lines('profile',jsonb_build_object('user_id',captain));
 if (result->'summary'->>'assigned_lines')::integer<>3 or(result->'summary'->>'active_lines')::integer<>2 or(result->'summary'->>'completed_lines')::integer<>1 or(result->'summary'->>'received_total')::integer<>15000 then raise exception 'captain profile summary wrong';end if;
 if result->'lines'->0?'front_path'then raise exception 'profile docs leaked';end if;
 perform set_config('request.jwt.claim.sub',other::text,true);
 begin perform public.tkt_lines('profile',jsonb_build_object('user_id',captain));raise exception 'unrelated profile read allowed';exception when others then if sqlerrm<>'PERMISSION_DENIED'then raise;end if;end;

end $$;
rollback;
